package com.xuhang.mealops.inventory.application;
import static org.assertj.core.api.Assertions.*; import java.math.*; import java.util.*; import java.util.concurrent.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.context.annotation.Import; import org.springframework.jdbc.core.JdbcTemplate; import com.xuhang.mealops.ingredient.application.IngredientRepository; import com.xuhang.mealops.ingredient.domain.*; import com.xuhang.mealops.inventory.domain.*; import com.xuhang.mealops.inventory.infrastructure.persistence.*; import com.xuhang.mealops.measurement.domain.*; import com.xuhang.mealops.support.PostgresTestConfiguration;
@SpringBootTest @Import(PostgresTestConfiguration.class) class InventoryConsumptionApplicationIT { @Autowired InventoryConsumptionApplicationService service; @Autowired InventoryBatchRepository batches; @Autowired IngredientRepository ingredients; @Autowired JdbcTemplate jdbc;
 @Test void insufficientInventoryDoesNotMutateBatchesOrLedger(){Ingredient i=ingredients.create(Ingredient.newIngredient(IngredientName.of("Atomic "+UUID.randomUUID())));var a=batches.create(InventoryBatch.newBatch(i.id(),Quantity.of(new BigDecimal("200"),Unit.GRAM),null));var b=batches.create(InventoryBatch.newBatch(i.id(),Quantity.of(new BigDecimal("100"),Unit.GRAM),null));assertThatThrownBy(()->service.consume(i.id(),new BigDecimal("400"),"g")).isInstanceOf(InsufficientInventoryException.class);assertThat(batches.findById(a.id()).orElseThrow().remainingQuantity().amount()).isEqualByComparingTo("200");assertThat(batches.findById(b.id()).orElseThrow().remainingQuantity().amount()).isEqualByComparingTo("100");assertThat(batches.findById(a.id()).orElseThrow().version()).isZero();assertThat(jdbc.queryForObject("select count(*) from inventory_transaction where ingredient_id=?",Integer.class,i.id())).isZero();}
 @Test void ledgerChildFailureRollsBackCasHeaderAndAllocation(){Ingredient i=ingredients.create(Ingredient.newIngredient(IngredientName.of("Rollback "+UUID.randomUUID())));var b=batches.create(InventoryBatch.newBatch(i.id(),Quantity.of(new BigDecimal("500"),Unit.GRAM),null));jdbc.execute("CREATE OR REPLACE FUNCTION fail_inventory_allocation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'test ledger failure'; END; $$");jdbc.execute("CREATE TRIGGER trg_test_fail_inventory_allocation BEFORE INSERT ON inventory_transaction_allocation FOR EACH ROW EXECUTE FUNCTION fail_inventory_allocation()");try{assertThatThrownBy(()->service.consume(i.id(),new BigDecimal("200"),"g")).isInstanceOf(RuntimeException.class);}finally{jdbc.execute("DROP TRIGGER IF EXISTS trg_test_fail_inventory_allocation ON inventory_transaction_allocation");jdbc.execute("DROP FUNCTION IF EXISTS fail_inventory_allocation()");}var after=batches.findById(b.id()).orElseThrow();assertThat(after.remainingQuantity().amount()).isEqualByComparingTo("500");assertThat(after.version()).isZero();assertThat(jdbc.queryForObject("select count(*) from inventory_transaction where ingredient_id=?",Integer.class,i.id())).isZero();assertThat(jdbc.queryForObject("select count(*) from inventory_transaction_allocation a join inventory_transaction t on t.id=a.transaction_id where t.ingredient_id=?",Integer.class,i.id())).isZero();}
 @Test void concurrentConsumptionHasOneWinner(){Ingredient i=ingredients.create(Ingredient.newIngredient(IngredientName.of("Concurrent "+UUID.randomUUID())));batches.create(InventoryBatch.newBatch(i.id(),Quantity.of(new BigDecimal("500"),Unit.GRAM),null));ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Boolean>> fs=new ArrayList<>();for(int n=0;n<2;n++)fs.add(pool.submit(()->{start.await(10,TimeUnit.SECONDS);try{service.consume(i.id(),new BigDecimal("400"),"g");return true;}catch(InsufficientInventoryException|InventoryConcurrentModificationException e){return false;}}));start.countDown();int wins=0;for(var f:fs)wins+=f.get(20,TimeUnit.SECONDS)?1:0;assertThat(wins).isEqualTo(1);var rows=batches.findAvailableByIngredientId(i.id());assertThat(rows).hasSize(1);assertThat(rows.get(0).remainingQuantity().amount()).isEqualByComparingTo("100");assertThat(rows.get(0).version()).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from inventory_transaction where ingredient_id=?",Integer.class,i.id())).isEqualTo(1);}catch(Exception e){throw new RuntimeException(e);}finally{pool.shutdownNow();}}
}
